public class Knapsack {

    public static int knapsack(int[] weight, int[] value, int W) {
        int n = weight.length;
        int[][] dp = new int[n + 1][W + 1];

        for (int i = 1; i <= n; i++) {
            for (int w = 0; w <= W; w++) {
                dp[i][w] = dp[i - 1][w]; // 담지 않는 경우
                if (w >= weight[i - 1]) {
                    dp[i][w] = Math.max(dp[i][w],
                        dp[i - 1][w - weight[i - 1]] + value[i - 1]); // 담는 경우
                }
            }
        }

        return dp[n][W];
    }

    public static void main(String[] args) {
        int[] weight = {2, 3, 4, 5};
        int[] value  = {3, 4, 5, 6};
        int W = 8;
        System.out.println(knapsack(weight, value, W)); // 10
    }
}
